import{_ as n,a0 as l,w as r,s as a,ao as i,I as o,x as e,a1 as s,A as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何在RHEL/CentOS 7.0中使用tmpfs | LCTT x X-CMD","titleTemplate":false,"description":"如何在RHEL/CentOS 7.0中使用tmpfs | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在RHEL/CentOS 7.0中使用tmpfs | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在RHEL/CentOS 7.0中使用tmpfs | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150520 How to Use tmpfs on RHEL or CentOS 7.0","title":"如何在RHEL/CentOS 7.0中使用tmpfs","tag":"201506","desc":""},"relativePath":"201506/20150520 How to Use tmpfs on RHEL or CentOS 7.0.md","filePath":"[post].md"}'),f={name:"201506/20150520 How to Use tmpfs on RHEL or CentOS 7.0.md"};function d(u,t,C,h,x,T){const p=l("Link");return r(),a("div",null,[t[13]||(t[13]=i(`<h1 id="如何在rhel-centos-7-0中使用tmpfs" tabindex="-1">如何在RHEL/CentOS 7.0中使用tmpfs <a class="header-anchor" href="#如何在rhel-centos-7-0中使用tmpfs" aria-label="Permalink to “如何在RHEL/CentOS 7.0中使用tmpfs”">​</a></h1><p>今天我們來談談 Centos 7 中的一個文件系統tmpfs，這是一個將所有文件和文件夾寫到虛擬內存中而不是實際寫到磁盤中的虛擬文件系統。這意味中tmpfs中所有的內容都是臨時的，在tmpfs卸載、系統重啓或者電源切斷後內容都將會丟失。技術的角度上來説，tmpfs將所有的內容放在內核內部緩存中並且會調整大小來容納文件，並可從交換空間中交換出不需要的頁。</p><p>CentOS默認使用tmpfs做的幾種用途可用df -h命令的輸出來看：</p><pre><code># df –h
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/tmpfs1.jpg" alt="df"></p><ul><li>/dev - 含有針對所有設備的設備文件的目錄</li><li>/dev/shm - 包含共享內存分配</li><li>/run - 用於系統日誌</li><li>/sys/fs/cgroup - 用於cgrpups， 一個針對特定進程限制、管制和審計資源利用的內核特性</li></ul><p>顯然，它也可以用作/tmp目錄， 你可以用下面的兩種方法來做到：</p><h3 id="使用systemctl來在-tmp中啓用tmpfs" tabindex="-1">使用systemctl來在/tmp中啓用tmpfs <a class="header-anchor" href="#使用systemctl來在-tmp中啓用tmpfs" aria-label="Permalink to “使用systemctl來在/tmp中啓用tmpfs”">​</a></h3><p>你可以使用systemctl命令在tmp目錄啓用tmpfs， 首先用下面的命令來檢查這個特性是否可用：</p><pre><code># systemctl is-enabled tmp.mount
</code></pre><p>這會顯示當先的狀態，（如果未啓用，）你可以使用下面的命令來啓用它：</p><pre><code># systemctl enable tmp.mount
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/tmpfs3.jpg" alt="systemctl"></p><p>這會讓系統控制/tmp目錄並在該目錄下掛載一個tmpfs文件系統。</p><h3 id="手動掛載-tmp文件系統" tabindex="-1">手動掛載/tmp文件系統 <a class="header-anchor" href="#手動掛載-tmp文件系統" aria-label="Permalink to “手動掛載/tmp文件系統”">​</a></h3><p>你可以在/etc/fstab中添加下面這行，來手工在/tmp下掛載 tmpfs。</p><pre><code>tmpfs /tmp tmpfs size=512m 0 0
</code></pre><p>接着運行這條命令</p><pre><code># mount –a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/tmpfs2.jpg" alt="df"></p><p>這應該就會在df -h中顯示tmpfs了，同樣也會在你下次重啓時自動掛載。</p><h3 id="立即創建tmpfs" tabindex="-1">立即創建tmpfs <a class="header-anchor" href="#立即創建tmpfs" aria-label="Permalink to “立即創建tmpfs”">​</a></h3><p>如果由於一些原因，你需要在一個文件夾下立即創建tmpfs，你可以使用下面的命令：</p><pre><code># mount -t tmpfs -o size=1G tmpfs /mnt/mytmpfs
</code></pre><p>當然你可以在size選項中指定你希望的大小和希望的掛載點，只要記住是有效的目錄就行了。</p><hr>`,26)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),s(p,{href:"http://linoxide.com/file-system/use-tmpfs-rhel-centos-7-0/"},{default:m(()=>[...t[0]||(t[0]=[e("http://linoxide.com/file-system/use-tmpfs-rhel-centos-7-0/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=e("作者：",-1)),s(p,{href:"http://linoxide.com/author/adriand/"},{default:m(()=>[...t[2]||(t[2]=[e("Adrian Dinu",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),s(p,{href:"https://github.com/geekpi"},{default:m(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),s(p,{href:"https://github.com/wxy"},{default:m(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("本文由 ",-1)),s(p,{href:"https://github.com/LCTT/TranslateProject"},{default:m(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),s(p,{href:"https://linux.cn/"},{default:m(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const b=n(f,[["render",d]]);export{L as __pageData,b as default};
